    {
        longside1 = a;
        if (b > c)
        {
            longside2 = b;
            longside3 = c;
        }
        else
        {
            longside2 = c;
            longside3 = b;
        }
    }
    else if(b >= a && b >= c)
    {
        longside1 = b;
        if ( a > c )
        {
            longside2 = a;
            longside3 = c;
        }
        else
        {
            longside2 = c;
            longside3 = a;
        }
    }
    else
    {
        longside1 = c;
        if ( a >= b )
        {
            longside2 = a;
            longside3 = b;
        }
        else
        {
            longside2 = b;
            longside3 = a;
        }
    }
    int diff = longside1 - longside2;
    int diff2 = longside2 - longside3;
